var BASE = 'https://toonily.com/';
var ICON = 'https://static.tnlycdn.com/2017/10/toonily_favicon2-300x300.png';
var E = [new KV('', '')];
var finished = false;

function saved(){ return document.getElementById('ketsu-final-data'); }
function done(){ try { window.webkit.messageHandlers.EXECUTE_KETSU_ASYNC.postMessage(''); } catch(e){} }
function clean(value){ return String(value || '').replace(/\s+/g, ' ').trim(); }
function abs(url){
  url = String(url || '').trim();
  if(!url) return '';
  if(url.indexOf('//') === 0) return 'https:' + url;
  try { return new URL(url, BASE).href; } catch(e){}
  if(url.charAt(0) === '/') return BASE.slice(0, -1) + url;
  return url;
}
function currentUrl(){
  try {
    var node = saved();
    var meta = JSON.parse((node && (node.textContent || node.innerText)) || '{}');
    if(meta.request && meta.request.url) return meta.request.url;
  } catch(e){}
  return location.href || BASE;
}
function imageUrl(img){
  if(!img) return '';
  var attrs = ['data-src','data-lazy-src','data-original','src'];
  for(var i=0; i<attrs.length; i++){
    var value = String(img.getAttribute(attrs[i]) || '').trim();
    if(value && value.indexOf('data:image') !== 0) return abs(value);
  }
  return '';
}
function htmlHeaders(referer){
  return [
    new KV('Accept','text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8'),
    new KV('Accept-Language','en-US,en;q=0.9'),
    new KV('Cookie','toonily-mature=1'),
    new KV('Referer',referer || BASE)
  ];
}
function imageHeaders(referer){
  return [
    new KV('Accept','image/avif,image/webp,image/apng,image/svg+xml,image/*,*/*;q=0.8'),
    new KV('Referer',referer || BASE)
  ];
}
function htmlReq(url, referer){ return new MR(abs(url) || BASE, 'GET', htmlHeaders(referer), null); }
function imageReq(url, referer){ return new MR(abs(url) || ICON, 'GET', imageHeaders(referer), null); }
function emptyExtra(){ return new Extra([new Commands('', E)], E); }
function errorCard(title, message){
  return new Data(imageReq(ICON,BASE),title,message || '','Manhwa','Toonily','','',false,htmlReq(BASE,BASE),false);
}
function finish(value){
  if(finished) return false;
  finished = true;
  var node = saved();
  if(node) node.textContent = JSON.stringify(value);
  done();
  return true;
}
function retry(run, attempt){
  if(attempt < 8) setTimeout(function(){ run(attempt + 1); }, 125);
  return attempt < 8;
}

function viewNumber(value){
  var text = clean(value).replace(/[^0-9.KMB]/gi,'');
  var number = parseFloat(text) || 0;
  if(/B$/i.test(text)) return number * 1000000000;
  if(/M$/i.test(text)) return number * 1000000;
  if(/K$/i.test(text)) return number * 1000;
  return number;
}
function cardRecordFromNode(node){
  var anchor = node.querySelector('.post-title a');
  var image = node.querySelector('.item-thumb img');
  var href = anchor ? abs(anchor.getAttribute('href') || anchor.href) : '';
  var title = clean(anchor && anchor.textContent);
  if(!href || !title) return null;

  var latest = node.querySelector('.chapter-item .chapter a');
  var rating = node.querySelector('[property="ratingValue"]') || node.querySelector('#averagerate');
  var stats = node.querySelectorAll('.manga-rate-view-comment .item');
  var views = stats.length ? clean(stats[stats.length - 1].textContent) : '';
  var badge = node.querySelector('.manga-title-badges');
  var latestRow = latest ? latest.closest('.chapter-item') : null;
  var date = latestRow ? latestRow.querySelector('.post-on, .chapter-release-date') : null;
  var ratingValue = parseFloat(clean(rating && rating.textContent)) || 0;
  var details = [];
  if(ratingValue) details.push('Rated ' + ratingValue.toFixed(1));
  if(views) details.push(views + (views.toLowerCase().indexOf('view') >= 0 ? '' : ' views'));

  return {
    rating: ratingValue,
    views: viewNumber(views),
    data: new Data(
      imageReq(imageUrl(image), currentUrl()),
      title,
      details.join(' | '),
      clean(badge && badge.textContent).toUpperCase() || 'MANHWA',
      'Toonily',
      clean(latest && latest.textContent),
      clean(date && date.textContent),
      false,
      htmlReq(href,currentUrl()),
      false
    )
  };
}
function collectCardRecords(root){
  root = root || document;
  var nodes = root.querySelectorAll('.page-item-detail.manga');
  var records = [];
  var seen = {};
  for(var i=0; i<nodes.length; i++){
    var record = cardRecordFromNode(nodes[i]);
    if(!record || !record.data.link || !record.data.link.url || seen[record.data.link.url]) continue;
    seen[record.data.link.url] = true;
    records.push(record);
  }
  return records;
}
function collectCards(root){
  return collectCardRecords(root).map(function(record){ return record.data; });
}
function collectSliderCards(){
  var anchors = document.querySelectorAll('.comic-slider-section li a[href*="/serie/"]');
  var cards = [];
  var seen = {};
  for(var i=0; i<anchors.length; i++){
    var href = abs(anchors[i].getAttribute('href') || anchors[i].href);
    var image = anchors[i].querySelector('img');
    var titleNode = anchors[i].querySelector('.txt');
    var title = clean(titleNode && titleNode.textContent) || clean(image && image.getAttribute('alt')).replace(/\s+manhwa$/i,'');
    if(!href || !title || seen[href]) continue;
    seen[href] = true;
    cards.push(new Data(
      imageReq(imageUrl(image),currentUrl()),title,'Recently added to Toonily','NEW','Toonily','','',false,htmlReq(href,currentUrl()),false
    ));
  }
  return cards;
}

function runMain(attempt){
  try {
    var records = collectCardRecords();
    var cards = records.map(function(record){ return record.data; });
    if(!cards.length && retry(runMain,attempt)) return;
    if(!cards.length) cards.push(errorCard('No Toonily releases found','Reload the module to try again.'));

    var slider = collectSliderCards();
    var byViews = records.slice().sort(function(a,b){ return b.views - a.views; }).map(function(record){ return record.data; });
    var byRating = records.slice().sort(function(a,b){
      if(b.rating !== a.rating) return b.rating - a.rating;
      return b.views - a.views;
    }).map(function(record){ return record.data; });
    var spotlight = byViews.length ? byViews.slice(0,1) : cards.slice(0,1);
    var spotlightUrl = spotlight.length && spotlight[0].link ? spotlight[0].link.url : '';
    var latest = cards.filter(function(card){ return !spotlightUrl || !card.link || card.link.url !== spotlightUrl; }).slice(0,15);
    var output = [];
    if(spotlight.length) output.push(new Output('wide11','horizontal','ultraWideFull','leading',new Section('Spotlight',true),null,spotlight));
    if(slider.length) output.push(new Output('normal4','horizontal','longTripletsDouble','leading',new Section('New on Toonily',true),null,slider));
    if(latest.length) output.push(new Output('normal4','horizontal','longTripletsDouble','leading',new Section('Latest Updates',true),null,latest));
    if(byViews.length) output.push(new Output('wide6','horizontal','doubletsFull','leading',new Section('Most Read',true),null,byViews.slice(0,10)));
    if(byRating.length) output.push(new Output('normal4','horizontal','longTripletsDouble','leading',new Section('Top Rated',true),null,byRating.slice(0,12)));
    finish(new MainPage(new MR('','GET',E,null),emptyExtra(),new JC(false,false,''),output));
  } catch(e){
    finish(new MainPage(new MR('','GET',E,null),emptyExtra(),new JC(false,false,''),[
      new Output('wide6','vertical','doubletsFull','',new Section('',true),null,[errorCard('Home page error',e.message)])
    ]));
  }
}
runMain(0);

