function Data(image,title,description,field1,field2,field3,field4,isChapter,link,openInWebView){
  this.image=image; this.title=title; this.description=description; this.field1=field1; this.field2=field2;
  this.field3=field3; this.field4=field4; this.isChapter=isChapter; this.link=link; this.openInWebView=openInWebView || false;
}
function Output(cellDesing,orientation,defaultLayout,paging,section,layout,data){
  this.cellDesing=cellDesing; this.orientation=orientation; this.defaultLayout=defaultLayout; this.paging=paging;
  this.section=section; this.layout=layout; this.data=data;
}
function Section(sectionName,separator){ this.sectionName=sectionName; this.separator=separator; }
function MainPage(request,extra,javascriptConfig,output){ this.request=request; this.extra=extra; this.javascriptConfig=javascriptConfig; this.output=output; }
function Search(request,extra,separator,javascriptConfig,output){ this.request=request; this.extra=extra; this.separator=separator; this.javascriptConfig=javascriptConfig; this.output=output; }
function Info(request,extra,javascriptConfig,output){ this.request=request; this.extra=extra; this.javascriptConfig=javascriptConfig; this.output=output; }
function Chapter(chapName,link,openInWebView){ this.chapName=chapName; this.link=link; this.openInWebView=openInWebView; }
function InfoOutput(image,title,link,description,genres,field1,field2,field3,field4,chapters){
  this.image=image; this.title=title; this.link=link; this.description=description; this.genres=genres;
  this.field1=field1; this.field2=field2; this.field3=field3; this.field4=field4; this.chapters=chapters;
}
function Chapters(request,extra,javascriptConfig,output){ this.request=request; this.extra=extra; this.javascriptConfig=javascriptConfig; this.output=output; }
function ChapterOutput(videos,images,text){ this.videos=videos; this.images=images; this.text=text; }

var BASE = 'https://toonily.com/';
var ICON = 'https://static.tnlycdn.com/2017/10/toonily_favicon2-300x300.png';
var E = [new KV('', '')];
var finished = false;

function saved(){ return document.getElementById('ketsu-final-data'); }
function done(){ try { window.webkit.messageHandlers.EXECUTE_KETSU_ASYNC.postMessage(''); } catch(e){} }
function clean(value){ return String(value || '').replace(/\s+/g, ' ').trim(); }
function abs(url){
  url = String(url || '').trim();
  if(!url) return '';
  if(url.indexOf('//') === 0) return 'https:' + url;
  try { return new URL(url, BASE).href; } catch(e){}
  if(url.charAt(0) === '/') return BASE.slice(0, -1) + url;
  return url;
}
function currentUrl(){
  try {
    var node = saved();
    var meta = JSON.parse((node && (node.textContent || node.innerText)) || '{}');
    if(meta.request && meta.request.url) return meta.request.url;
  } catch(e){}
  return location.href || BASE;
}
function imageUrl(img){
  if(!img) return '';
  var attrs = ['data-src','data-lazy-src','data-original','src'];
  for(var i=0; i<attrs.length; i++){
    var value = String(img.getAttribute(attrs[i]) || '').trim();
    if(value && value.indexOf('data:image') !== 0) return abs(value);
  }
  return '';
}
function htmlHeaders(referer){
  return [
    new KV('Accept','text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8'),
    new KV('Accept-Language','en-US,en;q=0.9'),
    new KV('Cookie','toonily-mature=1'),
    new KV('Referer',referer || BASE)
  ];
}
function imageHeaders(referer){
  return [
    new KV('Accept','image/avif,image/webp,image/apng,image/svg+xml,image/*,*/*;q=0.8'),
    new KV('Referer',referer || BASE)
  ];
}
function htmlReq(url, referer){ return new MR(abs(url) || BASE, 'GET', htmlHeaders(referer), null); }
function imageReq(url, referer){ return new MR(abs(url) || ICON, 'GET', imageHeaders(referer), null); }
function emptyExtra(){ return new Extra([new Commands('', E)], E); }
function errorCard(title, message){
  return new Data(imageReq(ICON,BASE),title,message || '','Manhwa','Toonily','','',false,htmlReq(BASE,BASE),false);
}
function finish(value){
  if(finished) return false;
  finished = true;
  var node = saved();
  if(node) node.textContent = JSON.stringify(value);
  done();
  return true;
}
function retry(run, attempt){
  if(attempt < 8) setTimeout(function(){ run(attempt + 1); }, 125);
  return attempt < 8;
}

function allowedPage(url){
  try {
    var host = new URL(url).hostname.toLowerCase();
    return host === 'data.tnlycdn.com' || host === 'static.tnlycdn.com';
  } catch(e){ return false; }
}
function collectPages(){
  var nodes = document.querySelectorAll('.reading-content img.wp-manga-chapter-img, .reading-content .page-break img');
  var referer = currentUrl();
  var images = [];
  var seen = {};
  for(var i=0; i<nodes.length; i++){
    var url = imageUrl(nodes[i]);
    var alt = clean(nodes[i].getAttribute('alt')).toLowerCase();
    if(!url || seen[url]) continue;
    if(alt.indexOf('discord') >= 0 || /\/wp-content\/assets\/999\.png(?:\?|$)/i.test(url)) continue;
    if(!allowedPage(url)) continue;
    seen[url] = true;
    images.push(imageReq(url,referer));
  }
  return images;
}
function runChapter(attempt){
  try {
    var images = collectPages();
    if(!images.length && retry(runChapter,attempt)) return;
    if(!images.length) images.push(imageReq(ICON,BASE));
    finish(new Chapters(new MR('','',E,null),emptyExtra(),new JC(false,false,''),new ChapterOutput(null,images,null)));
  } catch(e){
    finish(new Chapters(new MR('','',E,null),emptyExtra(),new JC(false,false,''),new ChapterOutput(null,[imageReq(ICON,BASE)],null)));
  }
}
runChapter(0);
